#!/bin/sh
# Started by event-stage-screen-kiosk.service on tty1 (user "ess").
# Runs the sway compositor with a generated configuration; the kiosk agent
# inside the session manages output modes and one Chromium window per HDMI
# output (placement rules are written to $ESS_SWAY_DIR/rules).
set -eu
APP_DIR="${ESS_APP_DIR:-/opt/event-stage-screen}"
CFG="${XDG_RUNTIME_DIR:-/tmp}/ess-sway"
mkdir -p "$CFG"
[ -f "$CFG/rules" ] || : > "$CFG/rules"
cat > "$CFG/config" <<CONF
# Generated by event-stage-screen
xwayland disable
default_border none
default_floating_border none
focus_follows_mouse no
seat * hide_cursor 1000
output * bg #000000 solid_color
include $CFG/rules
exec env ESS_SWAY_DIR=$CFG $APP_DIR/.venv/bin/python -m stagescreen.kiosk
CONF
exec sway --config "$CFG/config"
